static inline const char *pv_translate(unsigned lang,const char *s){
    if(s&&(!strcmp(s,"PS5 mode: PC / H.264")||!strcmp(s,"PS5 mode: Portal / H.264"))){
        int pc=!strcmp(s,"PS5 mode: PC / H.264");
        if(lang==2||lang==3||lang==4||lang==5)return pc?"Modo PS5: PC / H.264":"Modo PS5: Portal / H.264";
    }
    if(s){
        if(!strcmp(s,"PS5: PC fallback (experimental)")){
            if(lang==2||lang==3)return "PS5: modo PC alternativo (experimental)";
            if(lang==4||lang==5)return "PS5: modo PC alternativo (experimental)";
        }
        if(!strcmp(s,"Off: experimental Portal session envelope for PS5. On: legacy PC session envelope for PS5. Both request H.264; Sony may reject the session or codec. PS3 and PS4 are unchanged.")){
            if(lang==2||lang==3)return "Desligado: modo Portal experimental para PS5. Ligado: modo PC alternativo para PS5. Ambos solicitam H.264; a Sony pode recusar a sessão ou codec. PS3 e PS4 não mudam.";
            if(lang==4||lang==5)return "Desactivado: modo Portal experimental para PS5. Activado: modo PC alternativo para PS5. Ambos solicitan H.264; Sony puede rechazar la sesión o el códec. PS3 y PS4 no cambian.";
        }
    }
    if(!s||!pv_language(lang))return s;
    size_t len=strlen(s);
    /* Use the same non-inlined, length-checked lookup as the other locale
     * tables. Vita GCC diagnoses direct strcmp on shorter fixed arrays. */
    const char *v=pv_lookup(s,len,pv_catalogue_search_hint,&pv_catalogue_search_hint[lang],1);
    if(!v)v=pv_lookup(s,len,pv_ps5_notice,&pv_ps5_notice[lang],1);
    if(!v)v=pv_lookup(s,len,pv_ps5_test,&pv_ps5_test[lang],1);
    if(!v)v=pv_lookup(s,len,pv_library_metrics,&pv_library_metrics[lang],1);
    if(!v)v=pv_lookup(s,len,pv_text[0],pv_text[lang],PV_TEXT_COUNT);
    if(!v)v=pv_lookup(s,len,pv_extra[0],pv_extra[lang],PV_EXTRA_COUNT);
    if(!v)v=pv_lookup(s,len,pv_dynamic[0],pv_dynamic[lang],PV_DYNAMIC_COUNT);
    if(!v)v=pv_lookup(s,len,pv_filter_text[0],pv_filter_text[lang],2);
    if(!v)v=pv_lookup(s,len,pv_session_text[0],pv_session_text[lang],PV_SESSION_TEXT_COUNT);
    if(!v)v=pv_lookup(s,len,pv_about_exit[0],pv_about_exit[lang],PV_ABOUT_EXIT_COUNT);
    if(!v)v=pv_lookup(s,len,pv_control_help[0],pv_control_help[lang],PV_CONTROL_HELP_COUNT);
    if(!v)v=pv_lookup(s,len,pv_stream_settings[0],pv_stream_settings[lang],PV_STREAM_SETTINGS_COUNT);
    if(!v)v=pv_lookup(s,len,pv_dc_errors[0],pv_dc_errors[lang],PV_DC_ERRORS_COUNT);
    if(!v)v=pv_lookup(s,len,pv_security[0],pv_security[lang],PV_SECURITY_COUNT);
    if(!v)v=pv_lookup(s,len,pv_auto_vault[0],pv_auto_vault[lang],PV_AUTO_VAULT_COUNT);
    /* New catalogue labels must not override established menu/session keys. */
    if(!v)v=pv_lookup(s,len,pv_library_labels[0],pv_library_labels[lang],11);
    if(!v)v=pv_lookup(s,len,pv_theme_labels[0],pv_theme_labels[lang],7);
    if(!v)v=pv_lookup(s,len,pv_region_text[0],pv_region_text[lang],3);
    if(!v&&lang<6)v=pv_lookup(s,len,pv_update_text[0],pv_update_text[lang],22);
    if(!v&&lang<6)v=pv_lookup(s,len,pv_stream_option_text[0],pv_stream_option_text[lang],29);
    if(!v)v=pv_lookup(s,len,pv_direct_label,&pv_direct_label[lang],1);
    if(!v)v=pv_lookup(s,len,pv_direct_warning,&pv_direct_warning[lang],1);
    if(!v)v=pv_lookup(s,len,pv_manual_restart[0],pv_manual_restart[lang],2);
    if(!v&&lang<6)v=pv_lookup(s,len,pv_handoff_text[0],pv_handoff_text[lang],2);
    if(!v&&lang<6)v=pv_lookup(s,len,pv_beta_library[0],pv_beta_library[lang],8);
    return v?v:s;
}
#endif
